contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value, bytes memory _data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value, "insufficient test balance");

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        c.sendMoney(address(this), _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        assert(afterCount == beforeCount && (afterBalance == beforeBalance - _value || afterBalance == beforeBalance));
    }

    receive() external payable {}
    fallback() external payable {}
}

