pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value, bytes memory _data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.sendMoney(address(this), _value, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(afterCount == beforeCount && (afterBalance == beforeBalance - _value || afterBalance == beforeBalance));
    }

    function testFuzz_run(uint256 _value, bytes memory _data) public {
        _run(_value, _data);
    }

    receive() external payable {}

    fallback() external payable {}
